script:
(function () {
  'use strict';
  // Pension vs lump sum. Month 0 is the day the lump sum would be paid. The pension starts at
  // month D (it may be deferred), is paid at the start of each month until your life expectancy
  // (month L), then (joint option) at the survivor share until your spouse's life expectancy.
  // It rises by the COLA once a year from its start date.
  //   PV(r) = sum over k of payment(k) / (1 + i)^k,  i = (1 + r)^(1/12) - 1
  // Required return: the r at which PV(r) = lump sum (bisection on -50%..100%; PV falls as r rises).
  // Break-even: the first month the running total of pension payments reaches the lump sum.
  // Lump sum run-down: invested at the expected return, paying yourself the same payments.
  // Today's dollars: payment(k) / (1 + inflation)^(k/12).
  // CHECKS (Node, scratch tests): pension starting now, no COLA, $1,800 for 20 years at 5%:
  // PV = 1,800 x (1 - v^240) / (1 - v), v = 1.05^(-1/12) = $276,419.80 (closed form), and a
  // lump sum of that amount gives a required return of 5.00%; 0% return -> PV = 1,800 x 240 =
  // $432,000; break-even $250,000 / $1,800 = 138.9 -> 139th payment; deferring 5 years at 5%
  // divides PV by 1.05^5; joint 50% adds 900 x months of survivor payments at 0%.
  function payment(o, k) {
    if (k < o.D) return 0;
    var f = Math.pow(1 + o.cola, Math.floor((k - o.D) / 12));
    if (k < o.L) return o.M * f;
    if (o.joint && k < o.S) return o.s * o.M * f;
    return 0;
  }
  function pv(o, r) {
    var i = Math.pow(1 + r, 1 / 12) - 1, total = 0;
    for (var k = 0; k < o.end; k++) total += payment(o, k) / Math.pow(1 + i, k);
    return total;
  }
  // Return at which the pension is worth exactly the lump sum: {r} or {low}/{high} if outside range.
  function requiredReturn(o, lump) {
    var lo = -0.5, hi = 1;
    if (pv(o, lo) < lump) return { low: true };
    if (pv(o, hi) > lump) return { high: true };
    for (var n = 0; n < 80; n++) {
      var mid = (lo + hi) / 2;
      if (pv(o, mid) > lump) lo = mid; else hi = mid;
    }
    return { r: (lo + hi) / 2 };
  }

  function schedule(o, lump, ret, infl) {
    var i = Math.pow(1 + ret, 1 / 12) - 1, bal = lump, out = null, cum = 0, breakEven = null, real = 0, total = 0;
    var rows = [], yPay = 0, yReal = 0;
    for (var k = 0; k < o.end; k++) {
      var p = payment(o, k), pr = p / Math.pow(1 + infl, k / 12);
      cum += p; total += p; real += pr; yPay += p; yReal += pr;
      if (breakEven === null && lump > 0 && cum >= lump - 1e-9) breakEven = k + 1;
      if (out === null) {
        if (p > bal + 1e-9) { out = k + (p > 0 ? bal / p : 0); bal = 0; } else bal = (bal - p) * (1 + i);
      }
      if (k % 12 === 11 || k === o.end - 1) {
        rows.push({ age: o.age + Math.floor(k / 12), pay: yPay, real: yReal, cum: cum, bal: out === null ? bal : 0 });
        yPay = 0; yReal = 0;
      }
    }
    return { rows: rows, out: out, left: out === null ? bal : 0, breakEven: breakEven, total: total, real: real };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 || !isFinite(x) ? 0 : x); } };
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function fmtAge(a) { var y = Math.floor(a + 1e-9), m = Math.round((a - y) * 12); if (m === 12) { y += 1; m = 0; } return y + (m ? ' and ' + m + ' month' + (m > 1 ? 's' : '') : ''); }

  function update() {
    var joint = document.getElementById('plType').value === 'joint';
    document.getElementById('plJointGroup').hidden = !joint;
    var lump = num('plLump'), M = num('plMonthly'), age = Math.round(num('plAge')), start = Math.round(num('plStart')),
        cola = num('plCola'), life = Math.round(num('plLife')), survPct = num('plSurvPct'), spAge = Math.round(num('plSpAge')),
        spLife = Math.round(num('plSpLife')), ret = num('plReturn'), infl = num('plInflation');
    var error = document.getElementById('plError');
    var bad = [lump, M, age, start, cola, life, ret, infl].some(isNaN) || lump < 0 || M < 0 || age < 18 || age > 90 ||
              start < age || start > 95 || life <= start || life > 120 || cola < 0 || cola > 10 || ret < 0 || ret > 20 ||
              infl < 0 || infl > 15;
    if (joint) bad = bad || [survPct, spAge, spLife].some(isNaN) || survPct < 0 || survPct > 100 || spAge < 18 ||
                     spAge > 100 || spLife <= spAge || spLife > 120;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, a lump-sum age from 18 to 90, a pension start age no earlier than that (up to 95), ' +
                          'a life expectancy after the pension starts (up to 120), a return up to 20%, inflation up to 15% and an increase up to 10%.' +
                          (joint ? ' Your spouse\'s life expectancy must be above their age, and the survivor share 0 to 100%.' : '');
      return;
    }
    var o = { age: age, M: M, cola: cola / 100, D: (start - age) * 12, L: (life - age) * 12, joint: joint,
              s: survPct / 100, S: joint ? (spLife - spAge) * 12 : 0 };
    o.end = Math.max(o.L, o.S);
    var value = pv(o, ret / 100), sch = schedule(o, lump, ret / 100, infl / 100);
    var req = lump > 0 && M > 0 ? requiredReturn(o, lump) : null;

    set('plRequired', req === null ? '–' : (req.low ? 'Below -50%' : (req.high ? 'Above 100%' : pct.format(req.r))));
    set('plBetter', M <= 0 && lump <= 0 ? '–' : (Math.abs(value - lump) < 0.5 ? 'About equal' : (value > lump ? 'Monthly pension' : 'Lump sum')));
    set('plPensionValue', money.format(value));
    set('plBreakEven', sch.breakEven === null ? 'Never' : 'Age ' + fmtAge(age + sch.breakEven / 12));
    set('plTotal', money.format(sch.total));
    set('plTotalReal', money.format(sch.real));

    var summary;
    if (req === null) summary = 'Enter both the lump sum and the monthly pension to compare them.';
    else if (req.low) summary = 'The pension pays less in total than the lump sum, so the lump sum is worth more at any realistic return.';
    else if (req.high) summary = 'The lump sum would need to earn more than 100% a year to match the pension.';
    else summary = 'To pay the same income for as long as the pension would, the lump sum must earn ' + pct.format(req.r) +
      ' a year. At your expected ' + pct.format(ret / 100) + ', the pension is worth ' + money.format(value) + ' today, ' +
      money.format(Math.abs(value - lump)) + (value >= lump ? ' more' : ' less') + ' than the lump sum.';
    if (sch.breakEven !== null && sch.breakEven > o.L) summary += ' The pension only overtakes the lump sum through survivor payments after your life expectancy.';
    set('plSummary', summary);

    var first = M / Math.pow(1 + infl / 100, o.D / 12);
    var lastNom = payment(o, o.L - 1), last = lastNom / Math.pow(1 + infl / 100, (o.L - 1) / 12);
    set('plInflNote', M > 0 ? 'In today\'s dollars the first pension payment buys about ' + money.format(first) + ' and the payment at age ' + (life - 1) +
        ' about ' + money.format(last) + (cola === 0 ? ', because the pension has no cost-of-living increase.' : '.') : '');
    set('plDepletion', lump <= 0 || M <= 0 ? '' : (sch.out === null
      ? 'Invested at ' + pct.format(ret / 100) + ' and paying yourself the same income, the lump sum would last for as long as the pension and leave ' + money.format(sch.left) + ' for your heirs.'
      : 'Invested at ' + pct.format(ret / 100) + ' and paying yourself the same income, the lump sum would run out at about age ' + fmtAge(age + sch.out / 12) +
        (sch.out < o.L ? ', before your life expectancy.' : (sch.out < o.end ? ', before the survivor payments would end.' : '.'))));

    var body = document.getElementById('plSchedule');
    body.textContent = '';
    sch.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, money.format(row.pay), money.format(row.real), money.format(row.cum), money.format(row.bal)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('plForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
